STORY = [('kaiwen', '我不是跟你说了吗？想要情路顺利，工作上别走太近！', "Didn't I tell you yesterday? If you want romance to go smoothly, keep some distance at work!", [(208, '我不是跟你说了吗'), (209, '想要情路顺利'), (210, '工作上别走太近')], ''), ('kaiwen', '你就算沉不住气，也不能这么着急给她转正啊！', "Even if you lost your cool, you shouldn't have rushed to promote her like that!", [(213, '你就算沉不住气'), (214, '你也不能'), (215, '这么着急')], ''), ('kaiwen', '你刚才把人家小谷吓着了，你知不知道？', 'Do you realize you just frightened poor Xiaogu out of her wits?', [(217, '你刚才把人'), (218, '吓着了你知不知道')], ''), ('kaiwen', '你心里有什么憋屈的话，你说出来行不行？我求求你了。', "If something is eating at you inside, please just say it out loud — I'm begging you!", [(220, '你心里有什么憋屈的话'), (221, '你说出来行不行'), (222, '我求求你了')], ''), ('kaiwen', '你总自虐干吗呀？哪回你自虐，最后受苦的不是我们？', "Why do you always torture yourself? Every time you do, aren't we the ones who suffer too?", [(226, '你总自虐干吗呀'), (227, '你说哪回你自虐'), (228, '最后受苦')], ''), ('chun_yuqiao', '出去。', 'Get out.', [(231, '出去')], ''), ('kaiwen', '莫不是因为小谷的事，有点后悔了是不是？', "Wait — you're already regretting snapping at Xiaogu, aren't you?", [(234, '莫不是因为小谷的事'), (235, '有点后悔了是不是')], ''), ('kaiwen', '我说那些主意呢，你也别太当回事，别往心里去。', "Forget those silly ideas I gave you earlier; don't take them to heart.", [(239, '我说那些主意呢'), (241, '你也别太当回事'), (242, '别往心里去')], ''), ('kaiwen', '小谷这丫头路子野，说不定不会影响你们感情。', 'Xiaogu is a spirited girl — working together might not hurt your chances after all.', [(244, '小谷这丫头路子野'), (245, '说不定不会影响'), (246, '你们感情')], ''), ('chun_yuqiao', '你话那么多呢，能闭会儿嘴吗？', 'Why do you talk so much — can you shut your mouth for a minute?', [(247, '你话那么多呢'), (248, '能闭会儿嘴吗')], ''), ('chun_yuqiao', '你知道什么叫闭嘴吗？', 'Do you even know what shutting up means?', [(251, '你知道什么叫闭嘴吗')], ''), ('chun_yuqiao', '你查清楚辛惠美是在哪儿被拍的，还有找杰瑞把她日程给我。', 'Find out exactly where Xin Huimei was photographed, and get her schedule from her manager.', [(252, '你查清楚'), (253, '是在哪儿被拍的'), (254, '还有'), (255, '找杰瑞把她日程给我')], '')]
